import sys

def find_alphabet_order(names):
    # Create a graph to represent the order of characters
    graph = {chr(i): [] for i in range(ord('a'), ord('z') + 1)}

    # Build the graph based on the given names
    for i in range(len(names) - 1):
        name1 = names[i]
        name2 = names[i + 1]
        min_len = min(len(name1), len(name2))
        for j in range(min_len):
            if name1[j] != name2[j]:
                graph[name1[j]].append(name2[j])
                break
        else:
            if len(name1) > len(name2):
                return "Impossible"

    # Perform topological sort using Kahn's algorithm
    in_degree = {char: 0 for char in graph}
    for neighbors in graph.values():
        for neighbor in neighbors:
            in_degree[neighbor] += 1

    queue = [char for char in in_degree if in_degree[char] == 0]
    result = []

    while queue:
        char = queue.pop(0)
        result.append(char)
        for neighbor in graph[char]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == 26:
        return ''.join(result)
    else:
        return "Impossible"

